31:     const halfSize = bounds.getSize(new THREE.Vector3()).multiplyScalar(0.5);
32:     const centers = new Map<CarPiece, THREE.Vector3>();
33:     for (const piece of car.pieces) {
34:       const at = new THREE.Box3().setFromObject(piece.mesh).getCenter(new THREE.Vector3());
35:       centers.set(piece, at);
36:       if (piece.layer !== "exterior") continue;
37:       const radial = at.clone().sub(center);
38:       radial.set(
39:         radial.x / Math.max(halfSize.x, 0.01),
40:         radial.y / Math.max(halfSize.y, 0.01),
41:         radial.z / Math.max(halfSize.z, 0.01),
42:       );
43:       // Roof/bonnet lift, underfloor drops, side pieces spread sideways, ends move outwards.
44:       const offset = radial.clone().multiply(new THREE.Vector3(1.1, 0.9, 1.8));
45:       if (offset.lengthSq() < 0.01) offset.set(0, 1, 0);
46:       offset.normalize().multiplyScalar(3.8);
47:       this.pieces.set(piece, {
48:         home: piece.mesh.position.clone(),
49:         offset,
50:         delay: 0.14 * (1 - Math.min(1, Math.abs(radial.y))),
51:         amount: 0,
52:         opacity: 1,
53:       });
54:     }
